package cn.zhuatech.apautomation.deep;import cn.zhuatech.apautomation.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/admin/ap") public class DeepAdminController{private final DeepDomainService s;public DeepAdminController(DeepDomainService s){this.s=s;}@PostMapping("/invoices/{id}/approve")ApiResponse<?> approve(@PathVariable Long id){return ApiResponse.ok(s.approve(id));}@PostMapping("/invoices/{id}/payment-plans")ApiResponse<?> schedule(@PathVariable Long id,@Valid @RequestBody DeepDomainService.PaymentRequest r){return ApiResponse.ok(s.schedule(id,r));}@PostMapping("/payment-plans/{id}/pay")ApiResponse<?> pay(@PathVariable Long id,@Valid @RequestBody DeepDomainService.PayRequest r){return ApiResponse.ok(s.pay(id,r));}}
